def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    """Identifierar misstänkta intrångsförsök: portskanning och brute force."""
    portar_per_kalla = {}
    misslyckade = {}
    larm = []

    for pkt in packet_log:
        src = pkt.get("src_ip")
        if not src:
            continue

        # Portskanning: samma källa når många olika portar
        portar_per_kalla.setdefault(src, set()).add(pkt.get("dst_port"))

        # Brute force: upprepade misslyckade anslutningar
        if pkt.get("status") == "failed":
            misslyckade[src] = misslyckade.get(src, 0) + 1

    for src, portar in portar_per_kalla.items():
        if len(portar) >= 10:
            larm.append({"typ": "port_scan", "src_ip": src, "antal_portar": len(portar)})

    for src, antal in misslyckade.items():
        if antal >= 5:
            larm.append({"typ": "brute_force", "src_ip": src, "forsok": antal})

    return larm
