import os
import stat

def audit_file_permissions(directory: str) -> list[dict]:
    issues = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = os.stat(path).st_mode
            except OSError:
                continue
            findings = []
            if mode & stat.S_IWOTH:
                findings.append("world-writable")
            if mode & stat.S_IROTH and mode & stat.S_IXOTH:
                findings.append("world-readable-executable")
            if mode & stat.S_ISUID:
                findings.append("setuid")
            if findings:
                issues.append({
                    "path": path,
                    "permissions": oct(stat.S_IMODE(mode)),
                    "issues": findings,
                })
    return issues
