import math
from collections import Counter
from scapy.all import rdpcap, DNS, DNSQR

def analyze_dns_traffic(pcap_file: str) -> dict:
    def entropy(s: str) -> float:
        c = Counter(s)
        return -sum((n / len(s)) * math.log2(n / len(s)) for n in c.values()) if s else 0

    queries = []
    for pkt in rdpcap(pcap_file):
        if pkt.haslayer(DNS) and pkt.haslayer(DNSQR) and pkt[DNS].qr == 0:
            queries.append(pkt[DNSQR].qname.decode(errors="ignore").rstrip("."))

    domain_counts = Counter(".".join(q.split(".")[-2:]) for q in queries)
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}

    for q in queries:
        labels = q.split(".")
        subdomain = labels[0] if len(labels) > 2 else ""
        # DGA: hög entropi + lång label utan vokaler-täthet
        if len(subdomain) >= 12 and entropy(subdomain) > 3.5:
            suspicious["dga"].append(q)
        # Tunneling: mycket långa labels / lång total query
        if len(q) > 100 or any(len(l) > 52 for l in labels):
            suspicious["tunneling"].append(q)

    # Exfiltration: många unika subdomäner under samma basdomän
    subs = {}
    for q in queries:
        parts = q.split(".")
        if len(parts) > 2:
            subs.setdefault(".".join(parts[-2:]), set()).add(parts[0])
    for base, s in subs.items():
        if len(s) > 20:
            suspicious["exfiltration"].append(base)

    return {
        "total_queries": len(queries),
        "top_domains": domain_counts.most_common(10),
        "suspicious": {k: sorted(set(v)) for k, v in suspicious.items()},
    }
